insert into public.book_syllabus_topics (book_id, syllabus_topic_id, verification_status)
select books.id, syllabus_topics.id, 'needs_review'
from public.legacy_books legacy
join public.books books on books.slug = legacy.id
cross join lateral unnest(coalesce(legacy.syllabus_topic_ids, array[]::text[])) as linked_topics(topic_key)
join public.syllabus_topics on syllabus_topics.external_key = linked_topics.topic_key
on conflict (book_id, syllabus_topic_id) do nothing;

